<?php
declare(strict_types=1);

function render_import_module(): void
{
    ?>
    <section class="panel narrow"><div class="panel-heading"><div><h2>Import workbook</h2><p>Upload an XLSX workbook containing the <strong>2026</strong> and <strong>SPLIT 2026</strong> worksheets. Existing records will not be overwritten.</p></div></div>
        <div class="alert warning">This workbook uses grouped headers and repeated Amount, Quantity, Unit, Date, and Time columns. The import preview maps each stage by its verified column position, flags questionable values, and leaves each stage uncompleted.</div>
        <?php if (!class_exists(ZipArchive::class)): ?><div class="alert error">XLSX reading requires PHP's Zip extension. In XAMPP, enable <code>extension=zip</code> in <code>php.ini</code> and restart Apache.</div><?php endif; ?>
        <form method="post" enctype="multipart/form-data" class="form-stack"><?= csrf_field() ?><input type="hidden" name="action" value="import_preview"><label>New workbook group name (optional)<input name="workbook_group" maxlength="30" pattern="[A-Za-z0-9][A-Za-z0-9 ._-]{0,29}" placeholder="For example, 2027"><small>Enter a name to import both source worksheets into a separate group. Leave blank to keep the existing 2026 and SPLIT 2026 groups.</small></label><label>Excel workbook (.xlsx)<input type="file" name="workbook" accept=".xlsx" required></label><p class="form-help">The original upload is processed as a read-only source. Preview and validate the mapped rows before committing.</p><button class="button primary" <?= class_exists(ZipArchive::class) ? '' : 'disabled' ?>>Preview import</button></form>
        <?php if (!empty($_SESSION['import_preview'])): $preview = $_SESSION['import_preview']; ?><form method="post" class="import-preview"><?= csrf_field() ?><input type="hidden" name="action" value="import_commit"><h3>Import preview<?= !empty($preview['workbook_group']) ? ' · ' . h($preview['workbook_group']) : '' ?></h3><?php if (!empty($preview['workbook_group'])): ?><p>Both source worksheets will be imported under the new workbook group <strong><?= h($preview['workbook_group']) ?></strong>.</p><?php endif; ?><p><?= count($preview['rows']) ?> source rows · <?= count($preview['errors']) ?> blocking issues · <?= count($preview['warnings'] ?? []) ?> value warnings · <?= count($preview['duplicates']) ?> exact possible duplicates · <?= (int)($preview['ignored'] ?? 0) ?> continuation rows ignored</p><?php if ($preview['errors']): ?><ul class="issue-list"><?php foreach (array_slice($preview['errors'], 0, 20) as $issue): ?><li><?= h($issue) ?></li><?php endforeach; ?></ul><?php endif; ?><?php if (!empty($preview['warnings'])): ?><div class="alert warning"><strong>Review before importing:</strong><ul class="issue-list"><?php foreach (array_slice($preview['warnings'], 0, 20) as $warning): ?><li><?= h($warning) ?></li><?php endforeach; ?></ul><?php if (count($preview['warnings']) > 20): ?><p>Showing 20 of <?= count($preview['warnings']) ?> warnings.</p><?php endif; ?></div><?php endif; ?><div class="table-wrap"><table><thead><tr><th>Workbook group</th><th>Source worksheet</th><th>PR Number</th><th>Particulars</th><th>Requested By</th><th>PR Amount</th><th>PO Amount</th><th>ORS Amount</th><th>Payment Amount</th><th>Validation</th></tr></thead><tbody><?php foreach (array_slice($preview['rows'], 0, 20) as $row): ?><tr><td><?= h($row['worksheet']) ?></td><td><?= h($row['source_worksheet'] ?? $row['worksheet']) ?></td><td><?= h($row['pr_number'] ?? '') ?></td><td><?= h($row['particulars'] ?? '') ?></td><td><?= h($row['requested_by'] ?? '') ?></td><td><?= h($row['amount'] ?? '') ?></td><td><?= h($row['po_amount'] ?? '') ?></td><td><?= h($row['ors_amount'] ?? '') ?></td><td><?= h($row['payment_amount'] ?? '') ?></td><td><?= !empty($row['_duplicate']) ? 'Exact duplicate — will be skipped' : 'Ready' ?></td></tr><?php endforeach; ?></tbody></table></div><button class="button primary" <?= $preview['errors'] ? 'disabled' : '' ?>>Import ready records</button><a class="button secondary" href="index.php?page=import&discard=1">Discard preview</a></form><?php endif; ?>
    </section>
    <?php
}
